"""Thanh thương hiệu "Trạm Tín Hiệu | Min Trading" (ảnh đại diện nhúng sẵn, không cần file ảnh riêng)."""
import base64
import io

import streamlit as st

TITLE = "Trạm Tín Hiệu"
BRAND = "Min Trading"
TAGLINE = "Lọc tín hiệu kỹ thuật cổ phiếu Việt Nam · cập nhật cuối phiên"

_AVATAR_B64 = (
    ""
)

_CSS = """
<style>
.brand-hero{background:linear-gradient(135deg,var(--hero),#0E5A47 160%);color:var(--cream);
  padding:16px 20px;border-radius:14px;display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin:0 0 12px}
.brand-av{width:72px;height:72px;border-radius:50%;border:3px solid var(--cream);flex:none;
  box-shadow:0 0 0 4px rgba(252,248,223,.18)}
.brand-ttl{flex:1;min-width:200px}
.brand-ttl h1{margin:0!important;padding:0!important;font-size:22px!important;color:var(--cream)!important;line-height:1.3}
.brand-ttl h1 span{color:#E8C47C;font-weight:400}
.brand-ttl p{margin:2px 0 0!important;font-size:13px;color:var(--cream)!important;opacity:.8}
.brand-pill{display:inline-flex;gap:6px;align-items:center;font-size:12px;padding:4px 10px;border-radius:99px;
  background:rgba(252,248,223,.12);border:1px solid rgba(252,248,223,.25);color:var(--cream)}
.brand-dot{width:7px;height:7px;border-radius:50%;background:#2DD4A7}
</style>
"""


def page_icon():
    """Ảnh đại diện làm icon tab trình duyệt; lỗi thì dùng emoji."""
    try:
        from PIL import Image
        return Image.open(io.BytesIO(base64.b64decode(_AVATAR_B64)))
    except Exception:
        return "📈"


def render_header(data_note: str = ""):
    pill = f'<span class="brand-pill"><i class="brand-dot"></i>{data_note}</span>' if data_note else ""
    st.markdown(
        _CSS
        + f'<div class="brand-hero"><img class="brand-av" alt="{BRAND}" src="data:image/jpeg;base64,{_AVATAR_B64}">'
        f'<div class="brand-ttl"><h1>{TITLE} <span>|</span> {BRAND}</h1><p>{TAGLINE}</p></div>{pill}</div>',
        unsafe_allow_html=True,
    )
